INSERT INTO `sf_enterprise` VALUES (1,'天水花牛苹果（集团）有限责任公司','91620500561130147J','贾福昌',11250.00,'2010-10-11','有限责任公司（自然人投资或控股）','农、林、牧、渔专业及辅助性活动','存续（在营）','甘肃省天水市麦积区东柯河片区花牛集团花牛苹果产业园区一期1幢','农副产品收购、销售及进出口业务，果品贮藏、初加工，预包装食品、散装食品、包装材料销售，果品基地建设，技术推广及咨询，租赁服务','2010-10-11',NULL,'天水市市场监督管理局',NULL,'2026-09-01 00:00:00','2026-11-11 18:07:34',0);
