INSERT INTO `sf_enterprise_biz` VALUES (1,1,1,'🌿','plant','种植基地','在天水麦积区布局8个花牛苹果种植基地，共126个标准化地块，依托黄土高原海拔高、昼夜温差大的地理优势，种植元帅系花牛苹果，配套智能灌溉、物联网监测与无人机巡检。','基地数量','8 个','总面积','2450 亩','2026-09-01 00:00:00','2026-11-11 18:07:34',0),(2,1,2,'📦','pack','贮藏加工','自建花牛苹果产业园区，配备现代化分选包装车间与气调冷藏库，提供清洗、分拣、打蜡、分级、包装全链路加工服务，年加工能力覆盖全市花牛苹果产量。','年产量','3600 吨','年产值','2512 万元','2026-09-01 00:00:00','2026-11-11 18:07:34',0),(3,1,3,'🛒','sale','品牌销售','与SOHO中国潘石屹联合打造\"潘苹果\"品牌，建立覆盖线上线下渠道的销售网络，产品出口马尔代夫等国家，新增\"潘果汇\"\"嘉农汇\"等品牌矩阵。','核心品牌','潘苹果','出口国家','马尔代夫等','2026-09-01 00:00:00','2026-11-11 18:07:34',0),(4,1,4,'🧪','biz-agri','农资服务','配套农资供应、测土配方、植保飞防与农机作业服务，覆盖8个基地全产业链，年供应各类农资逾3800吨，并输出标准化技术服务包。','年供应量','3800 吨','服务基地','8 个','2026-09-01 00:00:00','2026-11-11 18:07:34',0),(5,1,5,'🚚','cold','冷链物流','自建预冷分选与冷链发运体系，配备冷藏车18辆、气调库6座，覆盖产地预冷—干线运输—终端配送全链路，产地到端损耗控制在5%以内。','冷藏车','18 辆','损耗控制','< 5%','2026-09-01 00:00:00','2026-11-11 18:07:34',0);
