INSERT INTO `sf_enterprise_expert` VALUES (1,1,1,'贾福昌',NULL,'首席农业专家','天水花牛苹果（集团）有限责任公司','2010-10-11','主持花牛苹果品种改良与栽培技术规程制定，牵头制定省级标准化生产技术体系。','2026-09-01 00:00:00','2026-11-11 18:07:34',0),(2,1,2,'李文清',NULL,'农业技术总监','甘肃省农科院果树研究所','2016-03-01','二十余年果业生产管理经验，主导水肥一体化与绿色防控技术落地。','2026-09-01 00:00:00','2026-11-11 18:07:34',0),(3,1,3,'王建国',NULL,'数字农业专家','西北农林科技大学园艺学院','2019-07-15','负责智慧果园物联网架构与数据模型建设，推动全链条数字化管理。','2026-09-01 00:00:00','2026-11-11 18:07:34',0),(4,1,4,'张淑芬',NULL,'质量与品牌总监','天水海关技术中心','2021-05-20','牵头溯源体系建设与品牌运营，成功推动花牛苹果出口马尔代夫。','2026-09-01 00:00:00','2026-11-11 18:07:34',0);
