INSERT INTO `sf_enterprise_timeline` VALUES (1,1,1,'2010年10月','公司成立','在甘肃省天水市麦积区注册成立，注册资本11250万元，启动花牛苹果全产业链整合与品牌化运营。','2026-09-01 00:00:00','2026-11-11 18:07:34',0),(2,1,2,'2012年06月','地理标志保护','\"花牛苹果\"获国家地理标志产品保护，品牌价值跻身全国苹果区域公用品牌前列。','2026-09-01 00:00:00','2026-11-11 18:07:34',0),(3,1,3,'2016年01月','中国农发基金注资','中国农发重点建设基金有限公司注资2400万元，成为战略股东，公司资本实力进一步增强。','2026-09-01 00:00:00','2026-11-11 18:07:34',0),(4,1,4,'2018年09月','\"潘苹果\"品牌发布','与SOHO中国潘石屹联合打造\"潘苹果\"品牌，建立O2O线上线下销售网络，品牌影响力辐射全国。','2026-09-01 00:00:00','2026-11-11 18:07:34',0),(5,1,5,'2024年','国家级龙头企业','获评2024年国家级农业产业化重点龙头企业，建成8个花牛苹果种植基地、126个标准化地块，年产花牛苹果约3600吨，品牌化运营进入新阶段。','2026-09-01 00:00:00','2026-11-11 18:07:34',0),(6,1,6,'2025年11月','首次出口马尔代夫','花牛苹果经天水海关检验检疫合格，首次出口马尔代夫，品牌国际化迈出关键一步。','2026-09-01 00:00:00','2026-11-11 18:07:34',0);
/*!40000 ALTER TABLE `sf_enterprise_timeline` ENABLE KEYS */;
UNLOCK TABLES;

