INSERT INTO `sf_alert_report` VALUES (1,'RPT001','2026年9月20日预警日报','daily','日报','全部基地汇总',12,8,3,'95%',NULL,'今日共收到20条预警信息，其中设备预警12条，农事预警8条。紧急级别预警3条，重要级别预警7条，提醒级别预警10条。整体处理率达到95%，较昨日提升2%。','今日设备预警主要集中在天水麦积区基地和天水秦州基地。其中水肥一体化设备离线预警2条，土壤湿度传感器异常预警3条，气象站设备离线预警1条。相关运维人员已及时响应处理。','农事预警方面，红蜘蛛虫害预警为最高优先级，已触发紧急级别。建议各基地密切关注虫害发展趋势，及时采取防治措施。此外，暴雨预警和大风预警也需要重点关注。','1. 针对红蜘蛛虫害预警，建议立即组织喷洒农药进行防治；2. 暴雨来临前做好果园排水准备；3. 大风天气检查加固防风设施；4. 加强设备巡检，确保设备正常运行。','系统自动','2026-09-20 09:00:00','2026-11-11 21:11:16','2026-11-11 21:11:16',0),(2,'RPT002','2026年第21周预警周报','weekly','周报','全部基地汇总',45,32,8,'92%',NULL,'本周共收到77条预警信息，整体处理率92%。设备预警45条，农事预警32条。紧急预警8条已全部处理。','本周设备预警主要集中在灌溉系统和气象监测设备，共处理故障设备12台，更换传感器5个。','农事预警以病虫害预警为主，红蜘蛛和蚜虫防治工作有序进行中。','加强设备日常维护，及时处理病虫害预警。','系统自动','2026-09-19 09:00:00','2026-11-11 21:11:16','2026-11-11 21:11:16',0),(3,'RPT003','2026年9月预警月报','monthly','月报','全部基地汇总',156,124,23,'94%',NULL,'本月共收到280条预警信息，设备预警156条，农事预警124条。紧急预警23条，整体处理率94%。','设备运行总体稳定，故障率较上月下降15%。','病虫害防治效果良好，红蜘蛛危害得到有效控制。','继续加强设备维护，做好夏季病虫害预防工作。','系统自动','2026-09-18 09:00:00','2026-11-11 21:11:16','2026-11-11 21:11:16',0),(4,'RPT004','2026年9月19日预警日报','daily','日报','全部基地汇总',10,7,2,'93%',NULL,'今日共收到17条预警信息，设备预警10条，农事预警7条。','设备运行正常，无重大故障。','农事预警以气象预警为主。','正常开展日常巡检工作。','系统自动','2026-09-19 09:00:00','2026-11-11 21:11:16','2026-11-11 21:11:16',0),(5,'RPT005','天水麦积区基地设备预警专项报告','custom','自定义报告','天水麦积区基地',35,0,5,'100%',NULL,'针对天水麦积区基地近期设备预警情况进行专项分析。','本月设备预警35条，已全部处理完毕。','-','建议增加设备巡检频次。','黄忠坚','2026-09-18 16:30:00','2026-11-11 21:11:16','2026-11-11 21:11:16',0),(6,'RPT006','2026年9月18日预警日报','daily','日报','全部基地汇总',8,6,1,'95%',NULL,'今日共收到14条预警信息。','设备运行稳定。','农事预警正常。','继续保持现有工作状态。','系统自动','2026-09-18 09:00:00','2026-11-11 21:11:16','2026-11-11 21:11:16',0),(7,'RPT007','2026年第20周预警周报','weekly','周报','全部基地汇总',42,28,6,'91%',NULL,'本周共收到70条预警信息。','设备维护工作正常开展。','农事预警处理及时。','加强设备预防性维护。','系统自动','2026-09-12 09:00:00','2026-11-11 21:11:16','2026-11-11 21:11:16',0),(8,'RPT008','病虫害预警趋势分析报告','custom','自定义报告','全部基地汇总',0,86,12,'98%',NULL,'分析近期病虫害预警趋势。','-'