INSERT INTO `sf_mall_post` VALUES (1,'刘友宝',NULL,'我家认养的花牛苹果今年挂果特别多，预计能收 80 斤左右！',NULL,NULL,NULL,0,0,'2026-10-22 14:00:00','approved',NULL,NULL,NULL,'2026-11-11 20:40:08','2026-11-11 20:40:08',0),(2,'陈晓梅',NULL,'上周去基地采摘，孩子第一次见到苹果长在树上，特别兴奋',NULL,NULL,NULL,0,0,'2026-10-22 10:30:00','approved',NULL,NULL,NULL,'2026-11-11 20:40:08','2026-11-11 20:40:08',0),(3,'王志强',NULL,'收到认养证书了，做工精致，扫码就能看到这棵树的所有农事记录',NULL,NULL,NULL,0,0,'2026-10-22 07:00:00','approved',NULL,NULL,NULL,'2026-11-11 20:40:08','2026-11-11 20:40:08',0),(4,'李文博',NULL,'请教一下，我的苹果出现几个黑斑，是什么情况？',NULL,NULL,NULL,0,0,'2026-10-22 03:30:00','approved',NULL,NULL,NULL,'2026-11-11 20:40:08','2026-11-11 20:40:08',0),(5,'周雅琴',NULL,'礼盒装的苹果包装很用心，送给客户的反响很好',NULL,NULL,NULL,0,0,'2026-10-22 00:00:00','approved',NULL,NULL,NULL,'2026-11-11 20:40:08','2026-11-11 20:40:08',0),(6,'吴国栋',NULL,'果园的环境真不错，鸟语花香的周末一日游',NULL,NULL,NULL,0,0,'2026-10-21 20:30:00','approved',NULL,NULL,NULL,'2026-11-11 20:40:08','2026-11-11 20:40:08',0),(7,'郑小雨',NULL,'今天刚下单，什么时候可以发货呀？',NULL,NULL,NULL,0,0,'2026-10-21 17:00:00','approved',NULL,NULL,NULL,'2026-11-11 20:40:08','2026-11-11 20:40:08',0),(8,'孙建国',NULL,'摘下来的苹果个头大，甜度不错，口感很好',NULL,NULL,NULL,0,0,'2026-10-21 13:30:00','approved',NULL,NULL,NULL,'2026-11-11 20:40:08','2026-11-11 20:40:08',0),(9,'马丽娟',NULL,'客服回复很及时，问题很快就解决了，点赞',NULL,NULL,NULL,0,0,'2026-10-21 10:00:00','approved',NULL,NULL,NULL,'2026-11-11 20:40:08','2026-11-11 20:40:08',0),(10,'胡海洋',NULL,'我家果树开了花，满树白花特别美，拍了很多照片',NULL,NULL,NULL,0,0,'2026-10-21 06:30:00','approved',NULL,NULL,NULL,'2026-11-11 20:40:08','2026-11-11 20:40:08',0),(11,'徐丽华',NULL,'有没有人一起去基地旅游的？',NULL,NULL,NULL,0,0,'2026-10-21 03:00:00','approved',NULL,NULL,NULL,'2026-11-11 20:40:08','2026-11-11 20:40:08',0),(12,'高志远',NULL,'认养果树比自己买水果有意思多了，能看到它一点点长大',NULL,NULL,NULL,0,0,'2026-10-20 23:30:00','approved',NULL,NULL,NULL,'2026-11-11 20:40:08','2026-11-11 20:40:08',0),(13,'林美玲',NULL,'配送很快，昨天下的单今天就到了，箱子包装很结实',NULL,NULL,NULL,0,0,'2026-10-20 20:00:00','approved',NULL,NULL,NULL,'2026-11-11 20:40:08','